add_task(async function test_skip_sync_accounts_load() {
  IMAPServer.open();
  SMTPServer.open();
  const emailUser = {
    name: "John Doe",
    email: "john.doe@imap.test",
    password: "abc12345",
    incomingHost: "testin.imap.test",
    outgoingHost: "testout.imap.test",
  };

  const dialog = await subtest_open_account_hub_dialog();
  await subtest_fill_initial_config_fields(dialog, emailUser);
  const footer = dialog.querySelector("account-hub-footer");
  const footerBack = footer.querySelector("#back");
  const configFoundTemplate = dialog.querySelector("email-config-found");

  await TestUtils.waitForCondition(
    () =>
      BrowserTestUtils.isVisible(configFoundTemplate.querySelector("#imap")),
    "The IMAP config option should be visible."
  );

  // Enter on the selected config should lead to the password template.
  const imapInput = configFoundTemplate.querySelector("#imap input");
  imapInput.focus();
  Assert.equal(
    document.querySelector("account-hub-container").shadowRoot.activeElement,
    imapInput,
    "The selected config should be focused before submitting"
  );
  EventUtils.synthesizeKey("KEY_Enter", {}, window);

  Assert.ok(
    BrowserTestUtils.isHidden(configFoundTemplate),
    "The config found template should be hidden."
  );
  await TestUtils.waitForCondition(
    () =>
      BrowserTestUtils.isVisible(dialog.querySelector("email-password-form")),
    "The email password form should be visible."
  );

  const emailPasswordTemplate = dialog.querySelector("email-password-form");
  await TestUtils.waitForCondition(
    () =>
      BrowserTestUtils.isVisible(
        emailPasswordTemplate.querySelector("#password")
      ),
    "The password form input should be visible."
  );
  const passwordInput = emailPasswordTemplate.querySelector("#password");

  EventUtils.synthesizeMouseAtCenter(passwordInput, {});

  // Entering the correct password should hide current subview.
  const inputEvent = BrowserTestUtils.waitForEvent(
    passwordInput,
    "input",
    true,
    event => event.target.value === "abc12345"
  );
  EventUtils.sendString("abc12345", window);
  await inputEvent;

  passwordInput.focus();
  EventUtils.synthesizeKey("KEY_Enter", {}, window);
  await BrowserTestUtils.waitForMutationCondition(
    emailPasswordTemplate,
    {
      attributes: true,
      attributeFilter: ["hidden"],
    },
    () => BrowserTestUtils.isHidden(emailPasswordTemplate)
  );

  // Cancelling here should prevent showing any sync accounts, and move to
  // the success view.
  Assert.ok(
    BrowserTestUtils.isVisible(footerBack),
    "The skip button should be visible."
  );

  EventUtils.synthesizeMouseAtCenter(footerBack, {});

  const imapAccount = await new Promise(resolve => {
    const listener = {
      onServerLoaded() {
        const matchingAccount = MailServices.accounts.accounts.find(
          account => account.identities[0]?.email === emailUser.email
        );
        if (matchingAccount) {
          MailServices.accounts.removeIncomingServerListener(listener);
          resolve(matchingAccount);
        }
      },
      onServerUnloaded() {},
      onServerChanged() {},
    };
    MailServices.accounts.addIncomingServerListener(listener);
    listener.onServerLoaded();
  });

  const successStep = dialog.querySelector("email-added-success");
  await BrowserTestUtils.waitForAttributeRemoval("hidden", successStep);

  await subtest_clear_status_bar();
  MailServices.accounts.removeAccount(imapAccount);
  MailServices.outgoingServer.deleteServer(
    MailServices.outgoingServer.servers.find(s => s.key != "smtp1")
  );
  await Services.logins.removeAllLoginsAsync();

  IMAPServer.close();
  SMTPServer.close();
  await subtest_close_account_hub_dialog(dialog, successStep);
});
